import{_ as d,o as e,c as r,a6 as o}from"./chunks/framework.B_q3ZJNF.js";const g=JSON.parse('{"title":"术语表","description":"","frontmatter":{},"headers":[],"relativePath":"mini-git-ts-course/glossary.md","filePath":"mini-git-ts-course/docs/glossary.md"}'),i={name:"mini-git-ts-course/glossary.md"};function a(c,t,s,n,l,m){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><p>全书术语按首教顺序收录;英文原名供对照检索。首教与定义的正本在各章正文,本页是回查入口。</p><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>一句话定义</th></tr></thead><tbody><tr><td>快照模型</td><td>snapshot model</td><td>Git 的每次提交记录的是当时整棵目录树的完整快照,不是相对上一版的差异清单。</td></tr><tr><td>工作区</td><td>working tree</td><td>你正在编辑、看得见的目录;与仓库之间隔着暂存区。</td></tr><tr><td>暂存区</td><td>staging area / index</td><td>工作区与仓库之间的缓冲层,本质是 .git/index 文件,记录「下一次提交将包含哪些文件的哪个版本」。</td></tr><tr><td>对象库</td><td>object database</td><td>.git/objects 下按内容寻址存放的全部不可变对象,是 Git 唯一的持久层。</td></tr><tr><td>底层命令</td><td>plumbing</td><td>操作单个机制的细粒度命令(hash-object、cat-file、write-tree 等);与之相对的 porcelain(瓷器)高层命令(add、commit、branch)只是它们的便捷组合。</td></tr><tr><td>内容寻址</td><td>content-addressed</td><td>对象的名字由其内容决定:对「类型+长度+内容」整体取 SHA-1,同内容必然同名。</td></tr><tr><td>SHA-1</td><td>SHA-1</td><td>Git 传统对象命名使用的 160 位哈希;40 个十六进制字符,前 2 位做目录、后 38 位做文件名。</td></tr><tr><td>对象头</td><td>object header</td><td>对象字节流开头的 <code>&lt;类型&gt; &lt;字节数&gt;\\0</code> 文本前缀,参与哈希计算,读回时用它区分对象种类。</td></tr><tr><td>松散对象</td><td>loose object</td><td>zlib 压缩后直接落在 objects/xx/yyyy… 的单个文件形态,与打包进 packfile 相对。</td></tr><tr><td>tree 对象</td><td>tree object</td><td>目录快照的二进制对象:一串 <code>&lt;模式&gt; &lt;名字&gt;\\0&lt;20 字节哈希&gt;</code> 条目,子目录递归指向另一棵 tree。</td></tr><tr><td>文件模式</td><td>file mode</td><td>tree 条目里的 6 位八进制权限串,普通文件 100644、可执行文件 100755、目录 40000、符号链接 120000。</td></tr><tr><td>十六进制转储</td><td>hex dump</td><td>把字节流按偏移量逐字节打印成十六进制的观察手段,调试二进制格式的第一工具。</td></tr><tr><td>Buffer</td><td>Buffer</td><td>Node 表示定长字节序列的类型,本课程用它做全部二进制编码与解析。</td></tr><tr><td>commit 对象</td><td>commit object</td><td>文本对象:指向一棵 tree、零到多个 parent、作者与提交者信息及时间戳。</td></tr><tr><td>父提交</td><td>parent commit</td><td>commit 对象里的 parent 字段;普通提交一个父,merge 提交两个,根提交零个。</td></tr><tr><td>提交图</td><td>commit graph</td><td>以提交为节点、父指针为边的有向无环图;分支、合并、变基都只是在这张图上的操作。</td></tr><tr><td>index 文件</td><td>index file</td><td>.git/index 的二进制格式:12 字节文件头 + 变长条目 + 路径名,暂存区的物理实体。</td></tr><tr><td>三态对比</td><td>three-state comparison</td><td>把工作区、暂存区、HEAD 三方两两比对得出 status;add 与 commit 各只搬动一跳。</td></tr><tr><td>引用</td><td>ref</td><td>指向某个对象的命名指针,通常是「含 40 位哈希的一行小文件」,存于 .git/refs 下。</td></tr><tr><td>符号引用</td><td>symbolic ref</td><td>内容为 <code>ref: &lt;另一个引用&gt;</code> 的间接引用,HEAD 就是指向当前分支的符号引用。</td></tr><tr><td>detached HEAD</td><td>detached HEAD</td><td>HEAD 直接指向某提交而非分支名;此时新提交不属于任何分支,切走后只能靠哈希找回。</td></tr><tr><td>编辑脚本</td><td>edit script</td><td>把文本 A 变成文本 B 的最少增删行操作序列,diff 的算法产物。</td></tr><tr><td>最长公共子序列</td><td>longest common subsequence</td><td>两序列按顺序共有的最长子序列;其补集即编辑脚本,是行级 diff 的算法基础。</td></tr><tr><td>unified diff</td><td>unified diff</td><td>Git 默认的 diff 输出格式:<code>@@ -a,b +c,d @@</code> 的 hunk 头加上下文行与 +/- 行。</td></tr><tr><td>hunk</td><td>hunk</td><td>unified diff 中一段连续改动的块:位置头、若干上下文行与增删行。</td></tr><tr><td>可达性</td><td>reachability</td><td>沿父指针能走到的提交集合;分支、tag、HEAD 是让对象「活下来」的根。</td></tr><tr><td>最近公共祖先</td><td>lowest common ancestor</td><td>两提交在图上公共祖先中离二者最近者,即 merge-base,三方合并的 base。</td></tr><tr><td>fast-forward</td><td>fast-forward</td><td>一方是另一方祖先时,合并只是把分支指针前移,不产生新提交。</td></tr><tr><td>三方合并</td><td>three-way merge</td><td>以 base 为基准分别对 ours/theirs 打改动:改不同处自动合入,改同一处才冲突。</td></tr><tr><td>冲突标记</td><td>conflict marker</td><td>合并器写入工作区的 <code>&lt;&lt;&lt;&lt;&lt;&lt;&lt;</code>/<code>=======</code>/<code>&gt;&gt;&gt;&gt;&gt;&gt;&gt;</code> 分隔块,标出两侧各自的版本。</td></tr><tr><td>merge 提交</td><td>merge commit</td><td>带两个父提交的提交,第一条边指向 ours、第二条指向 theirs。</td></tr><tr><td>pkt-line</td><td>pkt-line</td><td>Git 传输协议的帧格式:4 位十六进制长度前缀 + 载荷,0000 为分隔_flush 帧。</td></tr><tr><td>引用发现</td><td>ref discovery</td><td>传输握手第一步:客户端 GET/连接后收到对端 pkt-line 流出的全部引用与哈希。</td></tr><tr><td>remote-tracking 引用</td><td>remote-tracking ref</td><td>refs/remotes/&lt;名&gt;/ 下记录「远端分支上次同步时在哪」的本地引用,push/fetch 更新它而非远端。</td></tr><tr><td>bare 仓库</td><td>bare repository</td><td>没有工作区、只有 .git 内容的仓库,充当 push/fetch 的服务端落点。</td></tr></tbody></table>',3)])])}const h=d(i,[["render",a]]);export{g as __pageData,h as default};
